#include <gtest/gtest.h>
#include <limits>
#include "ocs2_legged_robot_adaptive/adaptive/TwoFeatureSixSubnetworkRbfWeightAdapter.h"
namespace ocs2 { namespace legged_robot_adaptive { namespace adaptive { namespace {
TwoFeatureRbfWeightAdapterSettings settings(){TwoFeatureRbfWeightAdapterSettings s;s.gamma.setOnes();s.outputScale<<2,3,4,5,6,7;return s;}
matrix_t basis(){matrix_t b(26,6);for(int i=0;i<6;++i)for(int j=0;j<26;++j)b(j,i)=1.+.01*j+.1*i;return b;}
TEST(TwoFeatureAdapter,ZeroSigma){EXPECT_TRUE(TwoFeatureSixSubnetworkRbfWeightAdapter(settings()).weightDerivative(basis(),vector6_t::Zero()).isZero());}
TEST(TwoFeatureAdapter,ZeroGamma){auto s=settings();s.gamma.setZero();vector6_t q=vector6_t::Ones();EXPECT_TRUE(TwoFeatureSixSubnetworkRbfWeightAdapter(s).weightDerivative(basis(),q).isZero());}
TEST(TwoFeatureAdapter,PositiveSigmaSign){vector6_t q=vector6_t::Zero();q(0)=2.;auto d=TwoFeatureSixSubnetworkRbfWeightAdapter(settings()).weightDerivative(basis(),q);EXPECT_GT(d.col(0).minCoeff(),0.);EXPECT_TRUE(d.rightCols(5).isZero());}
TEST(TwoFeatureAdapter,NegativeSigmaSign){vector6_t q=vector6_t::Zero();q(0)=-2.;auto d=TwoFeatureSixSubnetworkRbfWeightAdapter(settings()).weightDerivative(basis(),q);EXPECT_LT(d.col(0).maxCoeff(),0.);}
TEST(TwoFeatureAdapter,AxisIndependence){vector6_t q=vector6_t::Zero();q(4)=1.;auto d=TwoFeatureSixSubnetworkRbfWeightAdapter(settings()).weightDerivative(basis(),q);EXPECT_TRUE(d.leftCols(4).isZero());EXPECT_GT(d.col(4).norm(),0.);EXPECT_TRUE(d.col(5).isZero());}
TEST(TwoFeatureAdapter,OutputScaleFactor){vector6_t q=vector6_t::Ones();auto a=TwoFeatureSixSubnetworkRbfWeightAdapter(settings()).weightDerivative(basis(),q);auto s=settings();s.outputScale(2)*=2.;auto b=TwoFeatureSixSubnetworkRbfWeightAdapter(s).weightDerivative(basis(),q);EXPECT_TRUE(b.col(2).isApprox(2.*a.col(2),1e-14));}
TEST(TwoFeatureAdapter,GammaFactor){vector6_t q=vector6_t::Ones();auto a=TwoFeatureSixSubnetworkRbfWeightAdapter(settings()).weightDerivative(basis(),q);auto s=settings();s.gamma(3)*=2.;auto b=TwoFeatureSixSubnetworkRbfWeightAdapter(s).weightDerivative(basis(),q);EXPECT_TRUE(b.col(3).isApprox(2.*a.col(3),1e-14));}
TEST(TwoFeatureAdapter,BiasAndConstantReduction){matrix_t b=matrix_t::Zero(26,6);b.row(0).setOnes();vector6_t q;q<<1,-2,3,-4,5,-6;auto s=settings();s.outputScale.setOnes();auto d=TwoFeatureSixSubnetworkRbfWeightAdapter(s).weightDerivative(b,q);EXPECT_TRUE(d.row(0).transpose().isApprox(q,1e-14));EXPECT_TRUE(d.bottomRows(25).isZero());}
TEST(TwoFeatureAdapter,MatrixRegressorEquivalence){auto s=settings();auto b=basis();matrix_t w=matrix_t::Zero(26,6);for(int i=0;i<6;++i)w.col(i).setConstant(.1*(i+1));vector_t theta(156);for(int i=0;i<6;++i)theta.segment(i*26,26)=w.col(i);matrix_t y=matrix_t::Zero(6,156);for(int i=0;i<6;++i)y.block(i,i*26,1,26)=s.outputScale(i)*b.col(i).transpose();vector6_t direct;for(int i=0;i<6;++i)direct(i)=s.outputScale(i)*w.col(i).dot(b.col(i));EXPECT_TRUE((y*theta).isApprox(direct,1e-14));vector6_t q;q<<1,2,3,4,5,6;matrix_t expected=matrix_t::Zero(26,6);for(int i=0;i<6;++i)expected.col(i)=s.gamma(i)*s.outputScale(i)*b.col(i)*q(i);EXPECT_TRUE(TwoFeatureSixSubnetworkRbfWeightAdapter(s).weightDerivative(b,q).isApprox(expected,1e-14));}
TEST(TwoFeatureAdapter,EulerDt){auto a=TwoFeatureSixSubnetworkRbfWeightAdapter(settings());matrix_t z=matrix_t::Zero(26,6),d=a.weightDerivative(basis(),vector6_t::Ones());EXPECT_TRUE(a.eulerStep(z,d,.2).isApprox(2.*a.eulerStep(z,d,.1),1e-14));EXPECT_TRUE(a.eulerStep(z,d,0.).isApprox(z,1e-14));}
TEST(TwoFeatureAdapter,RejectsNegativeDt){auto a=TwoFeatureSixSubnetworkRbfWeightAdapter(settings());matrix_t z=matrix_t::Zero(26,6);EXPECT_THROW(a.eulerStep(z,z,-.1),std::invalid_argument);}
TEST(TwoFeatureAdapter,RejectsNanDt){auto a=TwoFeatureSixSubnetworkRbfWeightAdapter(settings());matrix_t z=matrix_t::Zero(26,6);EXPECT_THROW(a.eulerStep(z,z,std::numeric_limits<scalar_t>::quiet_NaN()),std::invalid_argument);}
TEST(TwoFeatureAdapter,RejectsInfiniteDt){auto a=TwoFeatureSixSubnetworkRbfWeightAdapter(settings());matrix_t z=matrix_t::Zero(26,6);EXPECT_THROW(a.eulerStep(z,z,std::numeric_limits<scalar_t>::infinity()),std::invalid_argument);}
TEST(TwoFeatureAdapter,RejectsInvalidBasis){auto a=TwoFeatureSixSubnetworkRbfWeightAdapter(settings());matrix_t bad=matrix_t::Zero(25,6);EXPECT_THROW(a.weightDerivative(bad,vector6_t::Zero()),std::invalid_argument);}
TEST(TwoFeatureAdapter,RejectsNonFiniteGamma){auto s=settings();s.gamma(0)=std::numeric_limits<scalar_t>::quiet_NaN();EXPECT_THROW(static_cast<void>(TwoFeatureSixSubnetworkRbfWeightAdapter(s)),std::invalid_argument);}
TEST(TwoFeatureAdapter,RejectsNonFiniteOutputScale){auto s=settings();s.outputScale(0)=std::numeric_limits<scalar_t>::infinity();EXPECT_THROW(static_cast<void>(TwoFeatureSixSubnetworkRbfWeightAdapter(s)),std::invalid_argument);}
TEST(TwoFeatureAdapter,RejectsNonFiniteBasis){matrix_t b=basis();b(0,0)=std::numeric_limits<scalar_t>::quiet_NaN();EXPECT_THROW(TwoFeatureSixSubnetworkRbfWeightAdapter(settings()).weightDerivative(b,vector6_t::Zero()),std::invalid_argument);}
TEST(TwoFeatureAdapter,RejectsNonFiniteSigma){vector6_t q=vector6_t::Zero();q(0)=std::numeric_limits<scalar_t>::infinity();EXPECT_THROW(TwoFeatureSixSubnetworkRbfWeightAdapter(settings()).weightDerivative(basis(),q),std::invalid_argument);}
TEST(TwoFeatureAdapter,EffectiveOutputRate){auto s=settings();auto b=basis();vector6_t q;q<<1,-2,3,-4,5,-6;auto d=TwoFeatureSixSubnetworkRbfWeightAdapter(s).weightDerivative(b,q);for(int i=0;i<6;++i){const scalar_t rate=s.outputScale(i)*b.col(i).dot(d.col(i));const scalar_t expected=s.gamma(i)*s.outputScale(i)*s.outputScale(i)*b.col(i).squaredNorm()*q(i);EXPECT_NEAR(rate,expected,1e-12);}}
}}}}
